class NestedInteger(object):
    def __init__(self, value=None):
        self._integer = None
        self._list = []
        if value is not None:
            if isinstance(value, int):
                self._integer = value
            elif isinstance(value, list):
                self._list = value

    def isInteger(self):
        return self._integer is not None

    def add(self, elem):
        self._list.append(elem)

    def setInteger(self, value):
        self._integer = value

    def getInteger(self):
        return self._integer

    def getList(self):
        return self._list

class Solution1:
    def deserialize(self, s):
        # Validate the input string for None or empty
        if not s:
            return NestedInteger()  
        workStack = []
        result = None
        sb = ''
        i = 0

        # Handle number initialization
        if s[i] != '[':
            while i < len(s) and (s[i].isdigit() or s[i] == '-'):
                sb += s[i]
                i += 1
            num = int(sb)
            return NestedInteger(num)

        # Main deserialization logic
        while i < len(s):
            if s[i] == '[':
                ni = NestedInteger()
                if workStack:
                    lastNi = workStack.pop()
                    lastNi.add(ni)
                    workStack.append(lastNi)
                workStack.append(ni)
                i += 1
            elif s[i] == ',':
                i += 1
            elif s[i] == ']':
                completedNi = workStack.pop()
                result = completedNi
                i += 1
            else:
                sb = ''
                while i < len(s) and (s[i].isdigit() or s[i] == '-'):
                    sb += s[i]
                    i += 1
                num = int(sb)
                if workStack:
                    ni = workStack.pop()
                else:
                    ni = NestedInteger()
                # Adding NestedInteger objects based on their current state
                if ni.isInteger():
                    ni.add(NestedInteger(num))
                elif ni.getList() and len(ni.getList()) != 0:
                    ni.add(NestedInteger(num))
                else:
                    ni.add(NestedInteger(num)) if i > 0 else ni.setInteger(num)
                workStack.append(ni)

        return ni if i == len(s) else result

